<?php $title='Login | ScholarHub'; require 'includes/header.php'; require 'config/db.php'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$st->execute([trim($_POST['email']??'')]);$u=$st->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){$_SESSION['user_id']=$u['id'];$_SESSION['role']=$u['role'];$_SESSION['name']=$u['name'];header('Location: '.($u['role']==='admin'?'admin/index.php':'profile.php'));exit;} $err='Invalid email or password.';} ?><div class="container py-5"><div class="row justify-content-center"><div class="col-md-5"><div class="card p-4"><h2>Login</h2><?php if($err): ?><div class="alert alert-danger"><?=e($err)?></div><?php endif; ?><form method="post"><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" type="password" name="password" placeholder="Password" required><button class="btn btn-primary w-100">Login</button></form><p class="mt-3">New student? <a href="register.php">Register</a></p></div></div></div></div><?php require 'includes/footer.php'; ?>
